    def findRotation(self, mat: List[List[int]], target: List[List[int]]) -> bool:
        n = len(mat)
        ok0 = ok90 = ok180 = ok270 = True
        for r in range(n):
            for c in range(n):
                v = mat[r][c]
                if v != target[r][c]:
                    ok0 = False
                if v != target[c][n - 1 - r]:
