class Solution {
    public int largestOverlap(int[][] img1, int[][] img2) {
        int n = img1.length;
        List<int[]> ones1 = new ArrayList<>();
        List<int[]> ones2 = new ArrayList<>();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (img1[r][c] == 1) ones1.add(new int[]{r, c});
                if (img2[r][c] == 1) ones2.add(new int[]{r, c});
            }
        }
        int span = 2 * n;
        int[][] counts = new int[span][span];
        int best = 0;
        for (int[] p1 : ones1) {
            for (int[] p2 : ones2) {
                int dr = p2[0] - p1[0] + n;
                int dc = p2[1] - p1[1] + n;
                int val = ++counts[dr][dc];
                if (val > best) best = val;
            }
        }
        return best;
    }
}

solutionCode.python:
class Solution:
    def largestOverlap(self, img1: List[List[int]], img2: List[List[int]]) -> int:
        n = len(img1)
        ones1 = [(r, c) for r in range(n) for c in range(n) if img1[r][c] == 1]
        ones2 = [(r, c) for r in range(n) for c in range(n) if img2[r][c] == 1]
        if not ones1 or not ones2:
            return 0
        counts = {}
        best = 0
        for r1, c1 in ones1:
            for r2, c2 in ones2:
                key = (r2 - r1, c2 - c1)
                val = counts.get(key, 0) + 1
                counts[key] = val
                if val > best:
                    best = val
        return best

