        ver = [[0] * n for _ in range(m)]
        best = 0
        for r in range(m):
            for c in range(n):
                if grid[r][c] == 1:
                    hor[r][c] = (hor[r][c - 1] if c > 0 else 0) + 1
                    ver[r][c] = (ver[r - 1][c] if r > 0 else 0) + 1
