                active.add((r, c))
                rows[r] += 1
                cols[c] += 1
                d1[r - c] += 1
                d2[r + c] += 1

        ans = []
        for qr, qc in queries:
            if rows[qr] > 0 or cols[qc] > 0 or d1[qr - qc] > 0 or d2[qr + qc] > 0:
                ans.append(1)
