                    nr, nc = qr + dr, qc + dc
                    if (nr, nc) in active:
                        active.remove((nr, nc))
                        rows[nr] -= 1
                        cols[nc] -= 1
                        d1[nr - nc] -= 1
                        d2[nr + nc] -= 1
        return ans

