        for r in range(len(nums) - 1, -1, -1):
            row = nums[r]
            total += len(row)
            for c, val in enumerate(row):
                d = r + c
                while len(buckets) <= d:
                    buckets.append([])
                buckets[d].append(val)
        res = []
        for b in buckets:
            res.extend(b)
        return res

